model Post {
  id        String   @id @default(cuid())
  title     String
  tags      String?
  content   String?
  coverUrl  String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
}

import mongoose, { Schema } from 'mongoose';

const PostSchema = new Schema(
  {
    title: String,
    tags: String,
    content: String,
    coverUrl: String,
  },
  {
    timestamps: true,
    toJSON: {
      virtuals: true,
      transform(doc, ret) {
        ret.id = ret._id;
        delete ret._id;
        delete ret.__v;
        return ret;
      },
    },
  },
);

const Post = mongoose.model('Post', PostSchema);

export default Post;

import prisma from '../db.js';

export const getPosts = async (req, res) => {
  const posts = await prisma.post.findMany({
    orderBy: { createdAt: 'desc' },
    select: { id: true, title: true, tags: true, coverUrl: true, createdAt: true },
  });
  res.json(posts);
};

